import * as T from '../../vendor/three/build/three.module.js';
export function buildMarket(ctx,arch,L){
 const{box,cyl,ball,pipe,cable,at,geometry,transform}=ctx.batch,{A,fabrics}=arch,{M,mat}=ctx,animated=[],disposables=[],metrics={stalls:0,bicycles:0,trees:0};
 const obstacle=(x,z,w,d,label)=>ctx.obstacles.push({x,z,w:w/2,d:d/2,label});
 const cloth=ctx.signage.textureCanvas(256,256,(c,w,h)=>{c.fillStyle='#e7dcc4';c.fillRect(0,0,w,h);for(let i=0;i<6;i++){c.strokeStyle='#52747b';c.lineWidth=i%2?2:6;c.strokeRect(7+i*5,7+i*5,w-14-i*10,h-14-i*10);}for(let y=48;y<220;y+=37)for(let x=47;x<223;x+=37){c.fillStyle='#58787b';c.beginPath();c.ellipse(x,y,5,9,.5,0,6.28);c.fill();c.fillStyle='#b97c64';c.beginPath();c.arc(x+5,y+6,3,0,6.28);c.fill();}});const clothMat=mat('#ffffff',{map:cloth,side:T.DoubleSide});
 function canopy(x,y,z,w,d,m){const g=new T.PlaneGeometry(w,d,12,6);g.rotateX(-Math.PI/2);const a=g.attributes.position,base=new Float32Array(a.array);for(let i=0;i<a.count;i++){const xx=a.getX(i)/(w/2),zz=a.getZ(i)/(d/2);a.setY(i,-.13*(1-xx*xx)+zz*.10);}g.computeVertexNormals();const mesh=new T.Mesh(g,m);mesh.position.set(x,y,z);mesh.castShadow=true;ctx.scene.add(mesh);animated.push({mesh,base:g.attributes.position.array.slice(),phase:ctx.rr(0,6)});disposables.push(g);box(x,y-.2,z+d/2,w,.35,.045,m);}
 function stall(s,i){const{x,z,kind}=s,w=3.6,d=2.1;metrics.stalls++;obstacle(x,z,w+.3,d+.2,kind+' market stall');for(const dx of[-w/2,w/2])for(const dz of[-d/2,d/2]){cyl(x+dx,2.08,z+dz,.038,2.5,A.wood);ball(x+dx,3.39,z+dz,.07,.10,.07,A.wood);}
  canopy(x,3.36,z,w+.44,d+.44,i%2?fabrics[2]:clothMat);arch.stock(kind,x,.84,z-.12,2.9);ctx.signage.sign(arch.spec[kind][0],x,2.83,z+1.11,2.4,.47,'#ead8b7','#554d40',0,false,arch.spec[kind][1]);for(let k=0;k<3;k++)box(x-.85+k*.85,.98,z-1.0,.65,.25,.60,A.woodLight);
  if(kind==='textiles'){for(const dx of[-1.15,1.15]){const g=new T.PlaneGeometry(.64,1.55,4,8);const m=new T.Mesh(g,clothMat);m.position.set(x+dx,2.28,z-.77);ctx.scene.add(m);animated.push({mesh:m,base:g.attributes.position.array.slice(),phase:i+dx,vertical:true});disposables.push(g);}}
 }
 L.stalls.forEach(stall);for(const x of[-2.8,2.8]){cyl(x,2.04,2.6,.055,2.5,A.wood);obstacle(x,2.6,.2,.2,'bazaar sign post');}ctx.signage.sign('गुलाबी बाज़ार',0,3.30,2.6,5.5,.65,'#365b55','#f0dfbb',0,false,'GULABI BAZAAR');
 function tree(x,z,s=1){obstacle(x,z,1.3*s,1.3*s,'urban tree planter');cyl(x,1.03,z,.78*s,.40,A.base);cyl(x,2.55*s,z,.10*s,3.4*s,A.wood);for(let k=0;k<5;k++){const a=k*1.256;pipe([x,2.6*s,z],[x+Math.cos(a)*.9*s,3.55*s,z+Math.sin(a)*.9*s],.06*s,A.wood);}for(let k=0;k<9;k++){const a=k*2.4;ball(x+Math.cos(a)*.83*s,3.9*s+(k%3)*.35*s,z+Math.sin(a)*.75*s,1.0*s,.68*s,.87*s,k%2?mat('#788263'):mat('#64765a'));}metrics.trees++;}
 for(const p of[[-7.5,21.3,.86],[8.5,21.3,.85],[-31,21,.8],[31,21,.8]])tree(...p);
 // A small open chaupar pavilion, not an unrelated national monument.
 arch.chhatri(0,.87,18.6,1.65);obstacle(0,18.6,4.2,4.2,'courtyard pavilion');for(const x of[-6.0,6.0]){box(x,1.22,18.8,2.1,.18,.66,A.cream);for(const dx of[-.8,.8])box(x+dx,1.01,18.8,.18,.33,.50,A.base);obstacle(x,18.8,2.1,.8,'stone seating');}
 // Front courtyard tea furniture: actors have reserved seats and clearance around walkers.
 for(const x of[-9,9]){cyl(x,1.45,15.1,.62,.08,A.woodLight);cyl(x,1.12,15.1,.055,.60,A.wood);for(const dx of[-.35,.35])pipe([x,1.12,15.1],[x+dx,.84,15.1+.28],.035,A.wood);obstacle(x,15.1,1.4,1.4,'tea table');for(const dz of[-1.05,1.05]){box(x,1.13,15.1+dz,.55,.13,.5,A.wood);for(const dx of[-.2,.2])box(x+dx,.96,15.1+dz,.06,.26,.4,A.wood);obstacle(x,15.1+dz,.6,.6,'tea stool');}for(const dx of[-.2,.2])cyl(x+dx,1.60,15.1,.07,.2,A.clay);}
 function bicycle(x,z,yaw){metrics.bicycles++;obstacle(x,z,1.9,.66,'parked bicycle');at(x,.76,z,yaw,()=>{const ring=new T.TorusGeometry(.36,.04,5,16);disposables.push(ring);for(const dx of[-.67,.67]){geometry(ring,M.black,transform(dx,.39,0));for(let k=0;k<6;k++){const a=k*Math.PI/3;pipe([dx,.39,0],[dx+Math.cos(a)*.32,.39+Math.sin(a)*.32,0],.008,M.metal);}}for(const[a,b]of[[[-.67,.39,0],[-.25,.99,0]],[[-.25,.99,0],[.19,.39,0]],[[.19,.39,0],[-.67,.39,0]],[[-.25,.99,0],[.43,1,0]],[[.43,1,0],[.19,.39,0]],[[.43,1,0],[.67,.39,0]],[[.43,1,0],[.43,1.18,0]]])pipe(a,b,.025,A.jade);box(-.25,1.04,0,.31,.07,.23,A.dark);box(.43,1.20,0,.08,.05,.55,A.dark);});}
 bicycle(-26,-3.0,0);bicycle(26,-3.0,Math.PI);
 function planter(x,z){cyl(x,1.07,z,.25,.46,A.clay);for(let k=0;k<5;k++)ball(x+Math.cos(k*1.3)*.15,1.42+(k%2)*.10,z+Math.sin(k*1.3)*.15,.17,.22,.17,M.leaf);obstacle(x,z,.6,.6,'potted plant');}
 for(const p of[[-15.8,12.2],[15.8,12.2],[-12,-3.5],[12,-3.5],[-27.2,-4],[27.2,-4]])planter(...p);
 // Street fixtures use actual mounted bulbs and a few sector lights, not one expensive light per pane.
 for(const[x,z]of[[-24,4.8],[24,4.8],[-15.0,11.6],[15.0,11.6]]){cyl(x,3.05,z,.065,4.4,A.dark);pipe([x,5.2,z],[x+.7,5.2,z],.04,A.dark);box(x+.7,5.13,z,.36,.12,.3,A.dark);box(x+.7,5.05,z,.28,.05,.23,A.glow);obstacle(x,z,.2,.2,'lamp post');ctx.signage.warmPool(x+.7,z,4,4);}
 for(const[x,y,z,power]of[[-22,3.4,-5.2,65],[-17,3.4,-5.2,65],[-6,3.3,-6.1,75],[6,3.3,-6.1,75],[18,3.4,-5.2,65],[24,3.4,-5.2,65],[-10,3.0,1.3,25],[10,3.0,1.3,25],[0,3.3,18.6,18]]){const light=new T.SpotLight('#ffc58b',power,12,Math.PI*.36,.75,2);light.position.set(x,y,z);light.target.position.set(x,z<-3?1.4:.84,z+(z<-3?-1.2:1.1));ctx.scene.add(light,light.target);ctx.nightLights.push({l:light,power,role:'interior'});}
 for(const side of[-1,1]){const x=side*27;box(x,2.15,-14,.20,.55,.36,M.metal);for(let i=0;i<3;i++)pipe([x,2.4,-14+i*.08],[x,6,-14+i*.08],.012,A.dark);cable([[x,6,-14],[side*18,5.65,-16.4],[side*12,6,-15.6]],.012,A.dark);}
 for(const s of L.north){at(s.x,.84,s.z,0,()=>{for(const dz of[-3.5,3.5])pipe([-s.w/2-.1,5.4,dz],[-s.w/2-.1,.03,dz],.045,A.base);});}
 function update(){if(ctx.state.paused)return;for(const a of animated){const p=a.mesh.geometry.attributes.position,t=ctx.state.time;for(let i=0;i<p.count;i++){const j=i*3,ox=a.base[j],oy=a.base[j+1],oz=a.base[j+2];if(a.vertical)p.setZ(i,oz+Math.sin(oy*2.4+t*.9+a.phase)*.025);else p.setY(i,oy+Math.sin(ox*1.4+oz+t*.75+a.phase)*.018);}p.needsUpdate=true;}}
 return{metrics,update,dispose(){disposables.forEach(g=>g.dispose());cloth.dispose();}};
}
